import { Order } from "../domain/order";
import { OrderLine } from "../domain/order-line";
import { OrderRepository } from "../domain/order-repository";
import { StockAllocationService } from "../domain/stock-allocation-service";
import { OrderDto, PlaceOrderCommand } from "./order-dto";
import { toOrderDto } from "./order-mapper";

export class PlaceOrderUseCase {
  constructor(
    private readonly orders: OrderRepository,
    private readonly stock: StockAllocationService,
  ) {}

  execute(command: PlaceOrderCommand): OrderDto {
    const lines = command.lines.map((line) => new OrderLine(line.productId, line.quantity));
    const order = new Order(this.orders.nextId(), lines, new Date());
    this.stock.reserve(order.lines);
    this.orders.save(order);
    return toOrderDto(order);
  }
}

